        'slug' => 'pwa-vs-app-store',
        'title' => 'Progressive Web App vs Native App: Which Does Your Business Need?',
        'meta_title' => 'Progressive Web App vs Native App: Which Does Your Business Need?',
        'description' => 'Progressive web app vs native app: what a PWA is, how it differs from an App Store app, and when it\'s the smarter choice for a small business that wants an app.',
        'keyword' => 'progressive web app',
        'type' => 'Comparison guide',
        'service' => 'services#pwa',
